#include <stdio.h>
#include <string.h>
#include "core.h"
typedef struct Trace { StarsDeleteBattleFleet fleets[4]; StarsI16 alerts,formats,answer; } Trace;
static StarsDeleteBattleFleet *fleet_at(void *v,StarsI16 n){Trace*t=(Trace*)v;if(n<0||n>=4)return (StarsDeleteBattleFleet*)0;return &t->fleets[n];}
static const StarsU8 *format_ids(void *v,StarsU16 id){Trace*t=(Trace*)v;t->formats++;if(id!=0x35b)return (const StarsU8*)0;return (const StarsU8*)"DELETE";}
static StarsI16 alert(void *v,const StarsU8 *s,StarsI16 style){Trace*t=(Trace*)v;t->alerts++;if(strcmp((const char*)s,"DELETE")!=0||style!=0x31)return 9;return t->answer;}
static void set_plan(StarsU8 *p,StarsU16 v){p[0]=(StarsU8)v;p[1]=(StarsU8)(v>>8);}
int main(void){Trace t;StarsDeleteBattlePlanInput i;StarsU8 count,plans[0x24*3];memset(&t,0,sizeof t);memset(&i,0,sizeof i);memset(plans,0,sizeof plans);t.fleets[0].player=1;t.fleets[0].plan=0;t.fleets[1].player=1;t.fleets[1].plan=2;t.fleets[2].player=1;t.fleets[2].plan=4;t.fleets[3].player=2;t.fleets[3].plan=1;count=3;set_plan(plans+0x24,0xa501);set_plan(plans+0x48,0xb602);i.current_player=1;i.fleet_count=4;i.fleet_at=fleet_at;i.plan_count=&count;i.plans=plans;i.format_ids=format_ids;i.alert=alert;i.context=&t;if(stars_delete_battle_plan(1,0,&i)!=1||count!=2||t.fleets[1].plan!=1||t.fleets[2].plan!=3||t.fleets[3].plan!=1||plans[0x24]!=0x12||plans[0x25]!=0xb6)return 1;memset(&t,0,sizeof t);t.fleets[0].player=1;t.fleets[0].plan=1;t.fleets[1].player=2;t.fleets[1].plan=0;count=2;memset(plans,0,sizeof plans);t.answer=2;i.current_player=1;i.fleet_count=2;if(stars_delete_battle_plan(1,1,&i)!=0||count!=2||t.alerts!=1||t.formats!=1)return 2;memset(&t,0,sizeof t);t.fleets[0].player=1;t.fleets[0].plan=1;t.fleets[1].player=1;t.fleets[1].plan=3;t.fleets[2].player=2;t.fleets[2].plan=0;count=3;set_plan(plans+0x24,0xc701);set_plan(plans+0x48,0xd802);t.answer=1;if(stars_delete_battle_plan(1,1,&i)!=1||count!=2||t.alerts!=1||t.fleets[1].plan!=2||t.fleets[2].plan!=0)return 3;if(plans[0x24]!=0x12||plans[0x25]!=0xd8)return 4;puts("DELETE_BATTLE_PLAN_SOURCE=PASS");return 0;}
